                        if (savedColors.size < 5) {
                            Box(
                                modifier = Modifier
                                    .size(48.dp)
                                    .shadow(2.dp, CircleShape)
                                    .background(if (lightMode) Color(0xFFE8EDF5) else Color(0xFF2A3A50), CircleShape)
                                    .border(1.5.dp, primaryColor.copy(alpha = 0.5f), CircleShape)
