// Helper function to parse event dates
fun parseEventDates(eventDateString: String): List<String> {
    val dates = mutableListOf<String>()

// Patterns to match: "April 9–10, 2026", "June 29 - July 2, 2026", "Feb 7, 2026", etc.
    val patterns = listOf(
// Single day: "Feb 7, 2026"
        Regex("""(\w+)\s+(\d+),\s+(\d{4})"""),
// Date range same month: "April 9–10, 2026" or "April 9-10, 2026"
        Regex("""(\w+)\s+(\d+)[–-](\d+),\s+(\d{4})"""),
// Date range different months: "June 29 - July 2, 2026"
        Regex("""(\w+)\s+(\d+)\s*[-–]\s*(\w+)\s+(\d+),\s+(\d{4})""")
    )

    val dateFormat = SimpleDateFormat("yyyy-MM-dd", Locale.US).apply {
        timeZone = TimeZone.getTimeZone("UTC")
    }
    val parseFormat = SimpleDateFormat("MMMM d, yyyy", Locale.US).apply {
        timeZone = TimeZone.getTimeZone("UTC")
    }

    try {
// Try cross-month range first (most specific): "June 29 - July 2, 2026"
        patterns[2].find(eventDateString)?.let { match ->
            val (startMonth, startDay, endMonth, endDay, year) = match.destructured
            val startDateStr = "$startMonth $startDay, $year"
            val endDateStr = "$endMonth $endDay, $year"
            val startDate = parseFormat.parse(startDateStr)
            val endDate = parseFormat.parse(endDateStr)
            if (startDate != null && endDate != null) {
                val cal = Calendar.getInstance(TimeZone.getTimeZone("UTC"))
                cal.time = startDate
                while (!cal.time.after(endDate)) {
                    dates.add(dateFormat.format(cal.time))
                    cal.add(Calendar.DAY_OF_MONTH, 1)
                }
            }
            return dates
        }

// Try same-month range pattern: "April 9–10, 2026"
        patterns[1].find(eventDateString)?.let { match ->
            val (month, startDay, endDay, year) = match.destructured
            val start = startDay.toInt()
            val end = endDay.toInt()

            for (day in start..end) {
                val dateStr = "$month $day, $year"
                parseFormat.parse(dateStr)?.let { parsedDate ->
                    dates.add(dateFormat.format(parsedDate))
                }
            }
            return dates
        }

// Try single day pattern: "Feb 7, 2026"
        patterns[0].find(eventDateString)?.let { match ->
            val (month, day, year) = match.destructured
            val dateStr = "$month $day, $year"
            parseFormat.parse(dateStr)?.let { parsedDate ->
                dates.add(dateFormat.format(parsedDate))
            }
            return dates
        }
    } catch (e: Exception) {
// If parsing fails, return empty list
    }

    return dates
}

fun insertCalendarEvent(context: android.content.Context, name: String, date: String, location: String): Long {
    val daysFmt = SimpleDateFormat("yyyy-MM-dd", Locale.US).apply { timeZone = TimeZone.getTimeZone("UTC") }
    val days = parseEventDates(date)
    val startMs = days.firstOrNull()?.let { daysFmt.parse(it)?.time } ?: return -1L
    val endMs = days.lastOrNull()?.let {
        val c = Calendar.getInstance(TimeZone.getTimeZone("UTC"))
        c.time = daysFmt.parse(it)!!
        c.add(Calendar.DAY_OF_MONTH, 1)
        c.timeInMillis
    } ?: (startMs + 24 * 60 * 60 * 1000L)

    // Query any available calendar — no VISIBLE filter so we don't miss hidden ones
    val calId = try {
        var id = -1L
        context.contentResolver.query(
            CalendarContract.Calendars.CONTENT_URI,
            arrayOf(CalendarContract.Calendars._ID),
            null, null, "${CalendarContract.Calendars._ID} ASC"
        )?.use { if (it.moveToFirst()) id = it.getLong(0) }
        id
    } catch (e: Exception) { -1L }

    if (calId == -1L) return -1L

    val values = ContentValues().apply {
        put(CalendarContract.Events.CALENDAR_ID, calId)
        put(CalendarContract.Events.TITLE, name)
        put(CalendarContract.Events.DTSTART, startMs)
        put(CalendarContract.Events.DTEND, endMs)
        put(CalendarContract.Events.ALL_DAY, 1)
        put(CalendarContract.Events.DESCRIPTION, "FBLA Competition — added via FBLA Hub")
        put(CalendarContract.Events.EVENT_LOCATION, location)
        put(CalendarContract.Events.HAS_ALARM, 1)
        put(CalendarContract.Events.EVENT_TIMEZONE, "UTC")
    }
    return try {
        context.contentResolver.insert(CalendarContract.Events.CONTENT_URI, values)
            ?.lastPathSegment?.toLongOrNull() ?: -1L
    } catch (e: Exception) { -1L }
}

// Animated button modifier for press effect
@Composable
fun Modifier.animatedClickable(
    onClick: () -> Unit
): Modifier {
    var isPressed by remember { mutableStateOf(false) }
    val scale by animateFloatAsState(
        targetValue = if (isPressed) 0.95f else 1f,
        animationSpec = spring(dampingRatio = Spring.DampingRatioMediumBouncy, stiffness = Spring.StiffnessLow),
        label = "button_scale"
    )

    return this
        .graphicsLayer {
            scaleX = scale
            scaleY = scale
        }
        .clickable(
            interactionSource = remember { MutableInteractionSource() },
            indication = null
        ) {
            onClick()
        }
        .pointerInput(Unit) {
            detectTapGestures(
                onPress = {
                    isPressed = true
                    tryAwaitRelease()
                    isPressed = false
                }
            )
        }
}

// Helper function to invert color lightness values (light ↔ dark)
fun invertColorValues(color: Color, invert: Boolean): Color {
    if (!invert) return color
    return Color(
        red = 1f - color.red,
        green = 1f - color.green,
        blue = 1f - color.blue,
        alpha = color.alpha
    )
}

@Composable
fun MainScreen() {
    var selectedTab by remember { mutableIntStateOf(2) }
    val auth = FirebaseAuth.getInstance()
    var currentUser by remember { mutableStateOf(auth.currentUser) }
    var showAuthFlow by remember { mutableStateOf(false) }
    var currentSubScreen by remember { mutableStateOf<String?>(null) }
    var showTutorial by remember { mutableStateOf(false) }

// User profile data for ResourcesScreen
    val db = FirebaseFirestore.getInstance()
    var userState by remember { mutableStateOf("") }
    var userChapter by remember { mutableStateOf("") }
    var userInstagram by remember { mutableStateOf("") }
    var hideConnections by remember { mutableStateOf(false) }
    var allowPeerSharing by remember { mutableStateOf(true) }

    val context = LocalContext.current
    val scope = rememberCoroutineScope()
    val activity = context as? androidx.activity.ComponentActivity

// Incoming share from other apps
    var shareReceiveText by remember { mutableStateOf<String?>(null) }
    var shareReceiveUri by remember { mutableStateOf<Uri?>(null) }
    var shareReceiveConnections by remember { mutableStateOf<List<UserProfile>>(emptyList()) }
    var shareReceiveLoadingConnections by remember { mutableStateOf(false) }
    var shareReceiveUploading by remember { mutableStateOf(false) }
    val showShareReceive = shareReceiveText != null || shareReceiveUri != null

// Load user profile data
    LaunchedEffect(auth.currentUser?.uid) {
        val uid = auth.currentUser?.uid
        if (uid != null) {
            db.collection("users").document(uid).addSnapshotListener { snapshot, _ ->
                val profile = snapshot?.toObject(UserProfile::class.java)
                userState = profile?.state ?: ""
                userChapter = profile?.school ?: ""
                userInstagram = profile?.chapterInstagram ?: ""
                hideConnections = profile?.hideConnections ?: false
                allowPeerSharing = profile?.allowPeerSharing ?: true
            }
        }
    }

// Persisted settings
    val bgOpacity by SettingsStore.bgOpacityFlow(context).collectAsState(initial = 0.9f)
    val lightMode by SettingsStore.lightModeFlow(context).collectAsState(initial = false)
    val primaryColor by SettingsStore.primaryColorFlow(context).collectAsState(initial = Color(0xFFFFB800))
    val savedColors by SettingsStore.savedColorsFlow(context).collectAsState(initial = listOf())
    val textSizeMultiplier by SettingsStore.textSizeFlow(context).collectAsState(initial = 1.0f)
    val isSimplifiedUI by SettingsStore.simplifiedUiFlow(context).collectAsState(initial = false)
    val notificationsEnabled by SettingsStore.notificationsEnabledFlow(context).collectAsState(initial = true)
    val notifMessages by SettingsStore.notifMessagesFlow(context).collectAsState(initial = true)
    val notifGroupMessages by SettingsStore.notifGroupMessagesFlow(context).collectAsState(initial = true)
    val notifConnectionRequests by SettingsStore.notifConnectionRequestsFlow(context).collectAsState(initial = true)
    val notifConnectionAccepted by SettingsStore.notifConnectionAcceptedFlow(context).collectAsState(initial = true)
    val notifEventReminders by SettingsStore.notifEventRemindersFlow(context).collectAsState(initial = true)
    val publicProfile by SettingsStore.publicProfileFlow(context).collectAsState(initial = true)
    val boldText by SettingsStore.boldTextFlow(context).collectAsState(initial = false)
    val reduceMotion by SettingsStore.reduceMotionFlow(context).collectAsState(initial = false)

// Register FCM token and request notification permission when logged in
    LaunchedEffect(auth.currentUser?.uid) {
        val uid = auth.currentUser?.uid ?: return@LaunchedEffect
        com.google.firebase.messaging.FirebaseMessaging.getInstance().token
            .addOnSuccessListener { token ->
                db.collection("users").document(uid).update(
                    mapOf(
                        "fcmToken" to token,
                        "notifEnabled" to true,
                        "notifMessages" to true,
                        "notifGroupMessages" to true,
                        "notifConnectionRequests" to true,
                        "notifConnectionAccepted" to true,
                        "notifEventReminders" to true
                    )
                )
            }
    }

// Process share intent helper
    fun processShareIntent(intent: Intent) {
        if (intent.action != Intent.ACTION_SEND) return
        when {
            intent.type == "text/plain" -> {
                val text = intent.getStringExtra(Intent.EXTRA_TEXT) ?: return
                shareReceiveText = text
                shareReceiveUri = null
            }
            intent.type?.startsWith("image/") == true || intent.type?.startsWith("video/") == true -> {
                val uri = if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.TIRAMISU)
                    intent.getParcelableExtra(Intent.EXTRA_STREAM, Uri::class.java)
                else @Suppress("DEPRECATION") intent.getParcelableExtra<Uri>(Intent.EXTRA_STREAM)
                if (uri != null) { shareReceiveUri = uri; shareReceiveText = null }
            }
        }
    }

// Check initial launch intent
    LaunchedEffect(Unit) {
        activity?.intent?.let { processShareIntent(it) }
        activity?.intent = Intent()
    }

// Listen for share intents while app is already running (onNewIntent)
    DisposableEffect(activity) {
        val listener = androidx.core.util.Consumer<Intent> { processShareIntent(it) }
        activity?.addOnNewIntentListener(listener)
        onDispose { activity?.removeOnNewIntentListener(listener) }
    }

// Load connections when share dialog opens
    LaunchedEffect(showShareReceive) {
        if (!showShareReceive || auth.currentUser?.uid == null) return@LaunchedEffect
        shareReceiveLoadingConnections = true
        val uid = auth.currentUser!!.uid
        db.collection("connections").document(uid).get().addOnSuccessListener { doc ->
            val uids = (doc.get("connectedUids") as? List<*>)?.mapNotNull { it as? String } ?: emptyList()
            if (uids.isEmpty()) { shareReceiveLoadingConnections = false; return@addOnSuccessListener }
            val loaded = mutableListOf<UserProfile>()
            var remaining = uids.size.coerceAtMost(20)
            uids.take(20).forEach { cUid ->
                db.collection("users").document(cUid).get().addOnSuccessListener { d ->
                    d.toObject(UserProfile::class.java)?.let { loaded.add(it) }
                    remaining--; if (remaining <= 0) { shareReceiveConnections = loaded.toList(); shareReceiveLoadingConnections = false }
                }.addOnFailureListener { remaining--; if (remaining <= 0) { shareReceiveConnections = loaded.toList(); shareReceiveLoadingConnections = false } }
            }
        }.addOnFailureListener { shareReceiveLoadingConnections = false }
    }

    val effectivePrimary = primaryColor
    val effectiveBgOpacity = bgOpacity

    val effectivePrimaryColor = invertColorValues(effectivePrimary, lightMode)

// Dynamic navigation bar colors
    val navBarBgColor = if (lightMode) Color(0xFFD8E4F8) else Color(0xFF000D1A)
    val navBarContentColor = if (lightMode) Color(0xFF1A1A2E) else Color.White

    var navBarBounds by remember { mutableStateOf(Rect.Zero) }

    val baseTypography = MaterialTheme.typography
    val effectiveTypography = if (boldText) Typography(
        displayLarge = baseTypography.displayLarge.copy(fontWeight = FontWeight.ExtraBold),
        displayMedium = baseTypography.displayMedium.copy(fontWeight = FontWeight.ExtraBold),
        displaySmall = baseTypography.displaySmall.copy(fontWeight = FontWeight.Bold),
        headlineLarge = baseTypography.headlineLarge.copy(fontWeight = FontWeight.ExtraBold),
        headlineMedium = baseTypography.headlineMedium.copy(fontWeight = FontWeight.Bold),
        headlineSmall = baseTypography.headlineSmall.copy(fontWeight = FontWeight.Bold),
        titleLarge = baseTypography.titleLarge.copy(fontWeight = FontWeight.ExtraBold),
        titleMedium = baseTypography.titleMedium.copy(fontWeight = FontWeight.Bold),
        titleSmall = baseTypography.titleSmall.copy(fontWeight = FontWeight.Bold),
        bodyLarge = baseTypography.bodyLarge.copy(fontWeight = FontWeight.SemiBold),
        bodyMedium = baseTypography.bodyMedium.copy(fontWeight = FontWeight.SemiBold),
        bodySmall = baseTypography.bodySmall.copy(fontWeight = FontWeight.SemiBold),
        labelLarge = baseTypography.labelLarge.copy(fontWeight = FontWeight.Bold),
        labelMedium = baseTypography.labelMedium.copy(fontWeight = FontWeight.Bold),
        labelSmall = baseTypography.labelSmall.copy(fontWeight = FontWeight.Bold),
    ) else baseTypography

    CompositionLocalProvider(
        LocalReduceMotion provides reduceMotion
    ) {
    MaterialTheme(typography = effectiveTypography) {
    Scaffold(
        containerColor = Color.Transparent,
        bottomBar = {
            if (currentSubScreen == null) {
                Box(modifier = Modifier.onGloballyPositioned { coords ->
                    navBarBounds = coords.boundsInRoot()
                }) {
                NavigationBar(containerColor = navBarBgColor, contentColor = navBarContentColor) {
                    listOf(
                        Triple(0, Icons.Filled.Person, "Profile"),
                        Triple(1, Icons.Filled.Event, "Events"),
                        Triple(2, Icons.Filled.Home, "Home"),
                        Triple(3, Icons.AutoMirrored.Filled.Article, "News"),
                        Triple(4, Icons.AutoMirrored.Filled.MenuBook, "Resources")
                    ).forEach { (index, icon, label) ->
                        NavigationBarItem(
                            selected = selectedTab == index,
                            onClick = { selectedTab = index },
                            icon = { Icon(icon, contentDescription = label) },
                            label = { Text(label, style = TextStyle(fontSize = (12 * textSizeMultiplier).sp)) },
                            colors = NavigationBarItemDefaults.colors(
                                selectedIconColor = effectivePrimaryColor,
                                selectedTextColor = effectivePrimaryColor,
                                unselectedIconColor = navBarContentColor.copy(alpha = 0.65f),
                                unselectedTextColor = navBarContentColor.copy(alpha = 0.65f),
                                indicatorColor = navBarContentColor.copy(alpha = 0.1f)
                            )
                        )
                    }
                }
                } // close onGloballyPositioned Box
            }
        }
    ) { padding ->
        val reduceMotionForCrossfade = LocalReduceMotion.current
        Crossfade(
            targetState = if (currentSubScreen != null) "subscreen" to currentSubScreen else "main" to selectedTab,
            animationSpec = if (reduceMotionForCrossfade) snap() else tween(durationMillis = 300, easing = LinearEasing),
            label = "screen_transition",
            modifier = Modifier.fillMaxSize()
        ) { (screenType, screenId) ->
            Box(
                modifier = Modifier
                    .padding(if (screenType == "subscreen") PaddingValues(0.dp) else padding)
                    .fillMaxSize()
            ) {
                if (screenType == "subscreen") {
                    when {
                        screenId == "settings" -> SettingsScreen(
                            onBack = { currentSubScreen = null },
                            onTutorialClick = { currentSubScreen = null; showTutorial = true },
                            primaryColor = primaryColor,
                            onPrimaryColorChange = { scope.launch { SettingsStore.savePrimaryColor(context, it) } },
                            bgOpacity = bgOpacity,
                            onBgOpacityChange = { scope.launch { SettingsStore.saveBgOpacity(context, it) } },
                            savedColors = savedColors,
                            onSavedColorsChange = { scope.launch { SettingsStore.saveSavedColors(context, it) } },
                            textSizeMultiplier = textSizeMultiplier,
                            onTextSizeChange = { scope.launch { SettingsStore.saveTextSize(context, it) } },
                            isSimplifiedUI = isSimplifiedUI,
                            onSimplifiedUIChange = { scope.launch { SettingsStore.saveSimplifiedUi(context, it) } },
                            lightMode = lightMode,
                            onLightModeChange = { scope.launch { SettingsStore.saveLightMode(context, it) } },
                            boldText = boldText,
                            onBoldTextChange = { scope.launch { SettingsStore.saveBoldText(context, it) } },
                            reduceMotion = reduceMotion,
                            onReduceMotionChange = { scope.launch { SettingsStore.saveReduceMotion(context, it) } },
                            notifEnabled = notificationsEnabled,
                            onNotifEnabledChange = { v ->
                                scope.launch { SettingsStore.saveNotificationsEnabled(context, v) }
                                val uid = FirebaseAuth.getInstance().currentUser?.uid ?: return@SettingsScreen
                                db.collection("users").document(uid).update("notifEnabled", v)
                            },
                            notifMessages = notifMessages,
                            onNotifMessagesChange = { v ->
                                scope.launch { SettingsStore.saveNotifMessages(context, v) }
                                val uid = FirebaseAuth.getInstance().currentUser?.uid ?: return@SettingsScreen
                                db.collection("users").document(uid).update("notifMessages", v)
                            },
                            notifGroupMessages = notifGroupMessages,
                            onNotifGroupMessagesChange = { v ->
                                scope.launch { SettingsStore.saveNotifGroupMessages(context, v) }
                                val uid = FirebaseAuth.getInstance().currentUser?.uid ?: return@SettingsScreen
                                db.collection("users").document(uid).update("notifGroupMessages", v)
                            },
                            notifConnectionRequests = notifConnectionRequests,
                            onNotifConnectionRequestsChange = { v ->
                                scope.launch { SettingsStore.saveNotifConnectionRequests(context, v) }
                                val uid = FirebaseAuth.getInstance().currentUser?.uid ?: return@SettingsScreen
                                db.collection("users").document(uid).update("notifConnectionRequests", v)
                            },
                            notifConnectionAccepted = notifConnectionAccepted,
                            onNotifConnectionAcceptedChange = { v ->
                                scope.launch { SettingsStore.saveNotifConnectionAccepted(context, v) }
                                val uid = FirebaseAuth.getInstance().currentUser?.uid ?: return@SettingsScreen
                                db.collection("users").document(uid).update("notifConnectionAccepted", v)
                            },
                            notifEventReminders = notifEventReminders,
                            onNotifEventRemindersChange = { v ->
                                scope.launch { SettingsStore.saveNotifEventReminders(context, v) }
                                val uid = FirebaseAuth.getInstance().currentUser?.uid ?: return@SettingsScreen
                                db.collection("users").document(uid).update("notifEventReminders", v)
                            },
                            hideConnections = hideConnections,
                            onHideConnectionsChange = { v ->
                                hideConnections = v
                                val uid = FirebaseAuth.getInstance().currentUser?.uid ?: return@SettingsScreen
                                db.collection("users").document(uid).update("hideConnections", v)
                            },
                            allowPeerSharing = allowPeerSharing,
                            onAllowPeerSharingChange = { v ->
                                allowPeerSharing = v
                                val uid = FirebaseAuth.getInstance().currentUser?.uid ?: return@SettingsScreen
                                db.collection("users").document(uid).update("allowPeerSharing", v)
                            },
                            onDeleteAccount = {
                                val db = FirebaseFirestore.getInstance()
                                val auth = FirebaseAuth.getInstance()
                                val uid = auth.currentUser?.uid
                                if (uid != null) {
                                    db.collection("users").document(uid).delete()
                                    db.collection("connections").document(uid).delete()
                                    auth.currentUser?.delete()
                                    currentSubScreen = null
                                }
                            }
                        )
                        screenId == "dress_code" -> DressCodeCheckerScreen(onBack = { currentSubScreen = null }, primaryColor = effectivePrimaryColor, bgOpacity = effectiveBgOpacity, textSizeMultiplier = textSizeMultiplier, lightMode = lightMode)
                        screenId == "find_links" -> MemberSearchScreen(onBack = { currentSubScreen = null }, primaryColor = effectivePrimaryColor, bgOpacity = effectiveBgOpacity, isSimplifiedUI = isSimplifiedUI, textSizeMultiplier = textSizeMultiplier, lightMode = lightMode)
                        screenId == "connection_requests" -> ConnectionRequestsScreen(onBack = { currentSubScreen = null }, primaryColor = effectivePrimaryColor, bgOpacity = effectiveBgOpacity, isSimplifiedUI = isSimplifiedUI, textSizeMultiplier = textSizeMultiplier, lightMode = lightMode)
                        screenId == "my_connections" -> MyConnectionsScreen(onBack = { currentSubScreen = null }, primaryColor = effectivePrimaryColor, bgOpacity = effectiveBgOpacity, isSimplifiedUI = isSimplifiedUI, textSizeMultiplier = textSizeMultiplier, lightMode = lightMode)
                        screenId == "messages" -> MessagesScreen(
                            primaryColor = effectivePrimaryColor,
                            bgOpacity = effectiveBgOpacity,
                            isSimplifiedUI = isSimplifiedUI,
                            textSizeMultiplier = textSizeMultiplier,
                            lightMode = lightMode,
                            onBack = { currentSubScreen = null },
                            onOpenChat = { userId, _ -> currentSubScreen = "chat_$userId" },
                            onOpenGroup = { groupId -> currentSubScreen = "group_$groupId" }
                        )
                        screenId is String && screenId.startsWith("group_") -> {
                            val groupId = screenId.removePrefix("group_")
                            GroupChatScreen(
                                groupId = groupId,
                                onBack = { currentSubScreen = "messages" },
                                primaryColor = effectivePrimaryColor,
                                bgOpacity = effectiveBgOpacity,
                                isSimplifiedUI = isSimplifiedUI,
                                textSizeMultiplier = textSizeMultiplier,
                                lightMode = lightMode
                            )
                        }
                        screenId == "classrooms" -> ClassroomsScreen(
                            primaryColor = effectivePrimaryColor,
                            bgOpacity = effectiveBgOpacity,
                            isSimplifiedUI = isSimplifiedUI,
                            textSizeMultiplier = textSizeMultiplier,
                            lightMode = lightMode,
                            onBack = { currentSubScreen = null },
                            onOpenClassroom = { classId -> currentSubScreen = "classroom_chat_$classId" }
                        )
                        screenId is String && screenId.startsWith("classroom_chat_") -> {
                            val classId = screenId.removePrefix("classroom_chat_")
                            ClassroomChatScreen(
                                classroomId = classId,
                                onBack = { currentSubScreen = "classrooms" },
                                primaryColor = effectivePrimaryColor,
                                bgOpacity = effectiveBgOpacity,
                                isSimplifiedUI = isSimplifiedUI,
                                textSizeMultiplier = textSizeMultiplier,
                                lightMode = lightMode
                            )
                        }
                        screenId is String && screenId.startsWith("chat_") -> {
                            val otherUserId = screenId.removePrefix("chat_")
                            ChatScreen(
                                otherUserId = otherUserId,
                                onBack = { currentSubScreen = null },
                                primaryColor = effectivePrimaryColor,
                                bgOpacity = effectiveBgOpacity,
                                isSimplifiedUI = isSimplifiedUI,
                                textSizeMultiplier = textSizeMultiplier,
                                lightMode = lightMode
                            )
                        }
                    }
                } else {
                    when (screenId as Int) {
                        0 -> {
                            if (currentUser == null) {
                                if (showAuthFlow) {
                                    AuthScreen(
                                        onLoginSuccess = {
                                            currentUser = auth.currentUser
                                            showAuthFlow = false
                                        },
                                        onBack = { showAuthFlow = false },
                                        lightMode = lightMode,
                                        primaryColor = effectivePrimaryColor,
                                        bgOpacity = effectiveBgOpacity
                                    )
                                } else {
                                    LoggedOutProfileScreen(onLoginClick = { showAuthFlow = true }, onTutorialClick = { showTutorial = true }, onSettingsClick = { currentSubScreen = "settings" }, primaryColor = effectivePrimaryColor, bgOpacity = effectiveBgOpacity, isSimplifiedUI = isSimplifiedUI, lightMode = lightMode)
                                }
                            } else {
                                ProfileScreen(
                                    onLogout = {
                                        auth.signOut()
                                        currentUser = null
                                    },
                                    onTutorialClick = { showTutorial = true },
                                    onSettingsClick = { currentSubScreen = "settings" },
                                    onFindLinksClick = { currentSubScreen = "find_links" },
                                    onConnectionRequestsClick = { currentSubScreen = "connection_requests" },
                                    onMyConnectionsClick = { currentSubScreen = "my_connections" },
                                    onMessagesClick = { currentSubScreen = "messages" },
                                    onClassroomsClick = { currentSubScreen = "classrooms" },
                                    onDressCodeClick = { currentSubScreen = "dress_code" },
                                    primaryColor = effectivePrimaryColor,
                                    bgOpacity = effectiveBgOpacity,
                                    textSizeMultiplier = textSizeMultiplier,
                                    isSimplifiedUI = isSimplifiedUI,
                                    lightMode = lightMode
                                )
                            }
                        }
                        1 -> EventsPlaceholder(effectivePrimary, effectiveBgOpacity, isSimplifiedUI, textSizeMultiplier, lightMode, userState)
                        2 -> HomeScreen(
                            primaryColor = effectivePrimaryColor,
                            bgOpacity = effectiveBgOpacity,
                            isSimplifiedUI = isSimplifiedUI,
                            textSizeMultiplier = textSizeMultiplier,
                            lightMode = lightMode,
                            onNavigate = { tab, subScreen ->
                                selectedTab = tab
                                currentSubScreen = subScreen
                            }
                        )
                        3 -> NewsScreen(effectivePrimary, effectiveBgOpacity, isSimplifiedUI, textSizeMultiplier, lightMode)
                        4 -> ResourcesScreen(effectivePrimary, effectiveBgOpacity, isSimplifiedUI, textSizeMultiplier, lightMode, userState, userChapter, userInstagram)
                    }
                }
            }
        }
    }
    } // end MaterialTheme
    } // end CompositionLocalProvider

    // Spotlight tutorial overlay — shown on top of the live app UI
    if (showTutorial) {
        androidx.compose.ui.window.Dialog(
            onDismissRequest = {},
            properties = androidx.compose.ui.window.DialogProperties(
                usePlatformDefaultWidth = false,
                dismissOnBackPress = false,
                dismissOnClickOutside = false
            )
        ) {
            SpotlightTutorialOverlay(
                onDismiss = { showTutorial = false },
                primaryColor = primaryColor,
                lightMode = lightMode,
                navBarBounds = navBarBounds // kept for signature compat, unused now
            )
        }
    }

// Share-receive dialog — shown on top of everything when another app shares to FBLA Hub
    if (showShareReceive) {
        val textColor = if (lightMode) Color(0xFF1A1A2E) else Color.White
        val textColorSecondary = if (lightMode) Color(0xFF1A1A2E).copy(alpha = 0.7f) else Color.White.copy(alpha = 0.75f)
        val storage = FirebaseStorage.getInstance()
        Dialog(onDismissRequest = {
            shareReceiveText = null; shareReceiveUri = null
            shareReceiveConnections = emptyList(); shareReceiveLoadingConnections = false
        }) {
            Surface(
                shape = RoundedCornerShape(24.dp),
                color = if (lightMode) Color.White else Color(0xFF1A2744),
                modifier = Modifier.fillMaxWidth()
            ) {
                Column(modifier = Modifier.padding(24.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
                    Text("Send to FBLA Hub", style = MaterialTheme.typography.titleMedium.copy(fontWeight = FontWeight.Bold), color = textColor)

// Preview of what's being shared
                    Surface(
                        shape = RoundedCornerShape(12.dp),
                        color = effectivePrimary.copy(alpha = 0.1f),
                        border = BorderStroke(1.dp, effectivePrimary.copy(alpha = 0.3f)),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Row(modifier = Modifier.padding(12.dp), verticalAlignment = Alignment.CenterVertically) {
                            Icon(
                                if (shareReceiveUri != null) Icons.Default.Image else Icons.Default.Link,
                                contentDescription = null, tint = effectivePrimary, modifier = Modifier.size(20.dp)
                            )
                            Spacer(modifier = Modifier.width(10.dp))
                            if (shareReceiveUri != null) {
                                AsyncImage(model = shareReceiveUri, contentDescription = null, contentScale = ContentScale.Crop,
                                    modifier = Modifier.size(60.dp).clip(RoundedCornerShape(8.dp)))
                            } else {
                                Text(
                                    text = shareReceiveText ?: "",
                                    style = MaterialTheme.typography.bodySmall,
                                    color = textColorSecondary,
                                    maxLines = 3,
                                    overflow = TextOverflow.Ellipsis
                                )
                            }
                        }
                    }

                    Text("Choose a member:", style = MaterialTheme.typography.labelMedium.copy(fontWeight = FontWeight.SemiBold), color = textColorSecondary)

                    if (shareReceiveUploading) {
                        Box(modifier = Modifier.fillMaxWidth().padding(16.dp), contentAlignment = Alignment.Center) {
                            Column(horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(8.dp)) {
                                CircularProgressIndicator(color = effectivePrimary)
                                Text("Sending...", style = MaterialTheme.typography.bodySmall, color = textColorSecondary)
                            }
                        }
                    } else if (shareReceiveLoadingConnections) {
                        Box(modifier = Modifier.fillMaxWidth().padding(16.dp), contentAlignment = Alignment.Center) {
                            CircularProgressIndicator(color = effectivePrimary, modifier = Modifier.size(28.dp))
                        }
                    } else if (shareReceiveConnections.isEmpty()) {
                        Text("No connections yet.", style = MaterialTheme.typography.bodyMedium, color = textColorSecondary)
                    } else {
                        Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            shareReceiveConnections.forEach { member ->
                                Surface(
                                    shape = RoundedCornerShape(12.dp),
                                    color = if (lightMode) Color(0xFFF0F4FF) else Color.White.copy(alpha = 0.07f),
                                    modifier = Modifier.fillMaxWidth().clickable {
                                        val uid = auth.currentUser?.uid ?: return@clickable
                                        val userName = auth.currentUser?.displayName ?: ""
                                        val uri = shareReceiveUri
                                        val text = shareReceiveText
                                        if (uri != null) {
                                            shareReceiveUploading = true
                                            scope.launch(kotlinx.coroutines.Dispatchers.IO) {
                                                try {
                                                    val bytes = context.contentResolver.openInputStream(uri)?.readBytes() ?: return@launch
                                                    val ref = storage.reference.child("shared_media/$uid/${System.currentTimeMillis()}.jpg")
                                                    ref.putBytes(bytes).addOnSuccessListener {
                                                        ref.downloadUrl.addOnSuccessListener { downloadUri ->
                                                            val msgId = db.collection("messages").document().id
                                                            val msg = ChatMessage(id = msgId, senderId = uid, receiverId = member.uid, message = "", timestamp = System.currentTimeMillis(), senderName = userName, attachmentUrl = downloadUri.toString(), attachmentName = "shared_image.jpg", attachmentType = "image")
                                                            db.collection("messages").document(msgId).set(msg)
                                                            shareReceiveUploading = false
                                                            shareReceiveText = null; shareReceiveUri = null; shareReceiveConnections = emptyList()
                                                            Toast.makeText(context, "Sent to ${member.name}", Toast.LENGTH_SHORT).show()
                                                        }
                                                    }.addOnFailureListener { shareReceiveUploading = false }
                                                } catch (e: Exception) { shareReceiveUploading = false }
                                            }
                                        } else if (text != null) {
                                            val msgId = db.collection("messages").document().id
                                            val url = extractUrl(text)
                                            val msg = if (url != null) {
                                                ChatMessage(id = msgId, senderId = uid, receiverId = member.uid, message = text, timestamp = System.currentTimeMillis(), senderName = userName, attachmentType = "link", attachmentUrl = url, attachmentName = urlDomain(url))
                                            } else {
                                                ChatMessage(id = msgId, senderId = uid, receiverId = member.uid, message = text, timestamp = System.currentTimeMillis(), senderName = userName)
                                            }
                                            db.collection("messages").document(msgId).set(msg)
                                            shareReceiveText = null; shareReceiveUri = null; shareReceiveConnections = emptyList()
                                            Toast.makeText(context, "Sent to ${member.name}", Toast.LENGTH_SHORT).show()
                                        }
                                    }
                                ) {
                                    Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.padding(12.dp)) {
                                        if (member.pfpUrl.isNotEmpty()) {
                                            AsyncImage(model = member.pfpUrl, contentDescription = null, contentScale = ContentScale.Crop,
                                                modifier = Modifier.size(38.dp).clip(CircleShape))
                                        } else {
                                            Box(modifier = Modifier.size(38.dp).clip(CircleShape).background(effectivePrimary), contentAlignment = Alignment.Center) {
                                                Text(member.name.take(1).uppercase(), color = Color.Black, style = MaterialTheme.typography.labelLarge.copy(fontWeight = FontWeight.Bold))
                                            }
                                        }
                                        Spacer(modifier = Modifier.width(12.dp))
                                        Column {
                                            Text(member.name, style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.SemiBold), color = textColor)
                                            if (member.school.isNotEmpty()) Text(member.school, style = MaterialTheme.typography.bodySmall, color = textColorSecondary)
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun LoggedOutProfileScreen(onLoginClick: () -> Unit, onTutorialClick: () -> Unit = {}, onSettingsClick: () -> Unit = {}, primaryColor: Color, bgOpacity: Float, isSimplifiedUI: Boolean, lightMode: Boolean = false) {
// Dynamic text color

    val textColor = if (lightMode) Color(0xFF1A1A2E) else Color.White
    val textColorSecondary = if (lightMode) Color(0xFF1A1A2E).copy(alpha = 0.8f) else Color.White.copy(alpha = 0.9f)
    val textColorTertiary = if (lightMode) Color(0xFF1A1A2E).copy(alpha = 0.75f) else Color.White.copy(alpha = 0.85f)

    Box(modifier = Modifier.fillMaxSize()) {
// Background — white in light mode, dark blue in dark mode
        Box(modifier = Modifier.fillMaxSize().background(
            if (lightMode) Color(0xFFF0F4FF) else Color(0xFF0A1628)
        ))
        if (!lightMode) {
            Box(modifier = Modifier.fillMaxSize().background(Color.Black.copy(alpha = bgOpacity)))
        }
// Gear icon always visible top-right
        IconButton(
            onClick = onSettingsClick,
            modifier = Modifier.align(Alignment.TopEnd).padding(top = 48.dp, end = 8.dp)
        ) {
            Icon(Icons.Default.Settings, contentDescription = "Settings", tint = primaryColor, modifier = Modifier.size(26.dp))
        }

        Column(modifier = Modifier.fillMaxSize(), horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.Center) {
            Image(
                painter = painterResource(R.drawable.fbla_tuff),
                contentDescription = null,
                modifier = Modifier.size(100.dp),
                contentScale = ContentScale.Fit
            )
            Spacer(modifier = Modifier.height(24.dp))
            Text("Sign in to view your profile", color = textColorSecondary)
            Spacer(modifier = Modifier.height(24.dp))
            Button(
                onClick = onLoginClick,
                colors = ButtonDefaults.buttonColors(containerColor = primaryColor),
                shape = RoundedCornerShape(12.dp),
                modifier = Modifier.width(200.dp).height(50.dp).pressScale()
            ) {
                Text("LOGIN OR SIGNUP", color = Color.Black, fontWeight = FontWeight.Bold)
            }
            Spacer(modifier = Modifier.height(12.dp))
            OutlinedButton(
                onClick = onTutorialClick,
                colors = ButtonDefaults.outlinedButtonColors(contentColor = primaryColor),
                border = BorderStroke(1.5.dp, primaryColor.copy(alpha = 0.5f)),
                shape = RoundedCornerShape(12.dp),
                modifier = Modifier.width(200.dp).height(50.dp).pressScale()
            ) {
                Icon(Icons.Default.PlayArrow, null, modifier = Modifier.size(16.dp))
                Spacer(modifier = Modifier.width(6.dp))
                Text("TUTORIAL", fontWeight = FontWeight.Bold)
            }
        }
    }
}

@Composable
fun ProfileScreen(
    onLogout: () -> Unit,
    onTutorialClick: () -> Unit = {},
    onSettingsClick: () -> Unit = {},
    onFindLinksClick: () -> Unit,
    onConnectionRequestsClick: () -> Unit,
    onMyConnectionsClick: () -> Unit,
    onMessagesClick: () -> Unit,
    onClassroomsClick: () -> Unit,
    onDressCodeClick: () -> Unit = {},
    primaryColor: Color,
    bgOpacity: Float,
    textSizeMultiplier: Float,
    isSimplifiedUI: Boolean,
    lightMode: Boolean = false
) {
    val auth = FirebaseAuth.getInstance()
    val db = FirebaseFirestore.getInstance()
    val context = LocalContext.current

    var profile by remember { mutableStateOf<UserProfile?>(null) }
    var isProfileLoading by remember { mutableStateOf(true) }
    var isEditing by remember { mutableStateOf(false) }
    var isProcessingImage by remember { mutableStateOf(false) }
    var unreadMessageCount by remember { mutableStateOf(0) }
    var unreadMessagesFrom by remember { mutableStateOf<List<String>>(emptyList()) }
    var showUnreadDialog by remember { mutableStateOf(false) }
    var showNetworkingMenu by remember { mutableStateOf(false) }
    var showLogoutConfirm by remember { mutableStateOf(false) }
    var showMyQr by remember { mutableStateOf(false) }
    var showQrScanner by remember { mutableStateOf(false) }
    var cropSourceUri by remember { mutableStateOf<Uri?>(null) }

    var name by remember { mutableStateOf("") }
    var firstName by remember { mutableStateOf("") }
    var lastName by remember { mutableStateOf("") }
    var email by remember { mutableStateOf("") }
    var chapter by remember { mutableStateOf("") }
    var year by remember { mutableStateOf("") }
    var statePref by remember { mutableStateOf("") }
    var bio by remember { mutableStateOf("") }
    var pfpUrl by remember { mutableStateOf("") }
    var instagram by remember { mutableStateOf("") }
    var twitter by remember { mutableStateOf("") }
    var facebook by remember { mutableStateOf("") }
    var linkedin by remember { mutableStateOf("") }
    var chapterInstagram by remember { mutableStateOf("") }
    var username by remember { mutableStateOf("") }
    var usernameLastChanged by remember { mutableStateOf(0L) }
    var usernameError by remember { mutableStateOf("") }
    var usernameAvailable by remember { mutableStateOf<Boolean?>(null) }
    var isCheckingUsername by remember { mutableStateOf(false) }

    val scope = rememberCoroutineScope()
    val clipboardManager = LocalClipboardManager.current

    var instagramError by remember { mutableStateOf("") }
    var twitterError by remember { mutableStateOf("") }
    var facebookError by remember { mutableStateOf("") }
    var linkedinError by remember { mutableStateOf("") }

    var showBusinessCardPreview by remember { mutableStateOf(false) }

    var connectionCount by remember { mutableIntStateOf(0) }
    var pendingRequestsCount by remember { mutableIntStateOf(0) }

    val effectiveBgOpacity = bgOpacity

    val textColor = if (lightMode) Color(0xFF1A1A2E) else Color.White
    val textColorSecondary = if (lightMode) Color(0xFF1A1A2E).copy(alpha = 0.8f) else Color.White.copy(alpha = 0.9f)
    val textColorTertiary = if (lightMode) Color(0xFF1A1A2E).copy(alpha = 0.75f) else Color.White.copy(alpha = 0.85f)

    // Pick image → open custom crop screen
    val pfpLauncher = rememberLauncherForActivityResult(ActivityResultContracts.GetContent()) { uri: Uri? ->
        uri?.let { cropSourceUri = it }
    }

    fun uploadCroppedBitmap(bitmap: Bitmap) {
        val uid = auth.currentUser?.uid ?: return
        isProcessingImage = true
        val out = ByteArrayOutputStream()
        bitmap.compress(Bitmap.CompressFormat.JPEG, 85, out)
        val bytes = out.toByteArray()
        val storageRef = FirebaseStorage.getInstance().reference.child("profile_pictures/$uid.jpg")
        storageRef.putBytes(bytes)
            .addOnSuccessListener {
                storageRef.downloadUrl.addOnSuccessListener { downloadUri ->
                    val url = downloadUri.toString()
                    pfpUrl = url
                    db.collection("users").document(uid)
                        .update("pfpUrl", url)
                        .addOnSuccessListener {
                            isProcessingImage = false
                            Toast.makeText(context, "Profile picture updated!", Toast.LENGTH_SHORT).show()
                        }
                        .addOnFailureListener { e ->
                            isProcessingImage = false
                            Toast.makeText(context, "Failed to save: ${e.message}", Toast.LENGTH_SHORT).show()
                        }
                }
            }
            .addOnFailureListener { e ->
                isProcessingImage = false
                Toast.makeText(context, "Upload failed: ${e.message}", Toast.LENGTH_SHORT).show()
            }
    }

    LaunchedEffect(Unit) {
        val uid = auth.currentUser?.uid
        if (uid != null) {
            db.collection("users").document(uid).addSnapshotListener { snapshot, error ->
                isProfileLoading = false
                if (error != null) return@addSnapshotListener
                val data = snapshot?.toObject(UserProfile::class.java)
                profile = data
                if (data != null && data.username.isEmpty()) {
                    val generatedUsername = generateRandomUsername()
                    val uid = auth.currentUser?.uid ?: return@addSnapshotListener
                    db.collection("usernames").document(generatedUsername).set(mapOf("uid" to uid))
                    db.collection("users").document(uid).update(mapOf("username" to generatedUsername, "usernameLastChanged" to 0L))
                }
                if (data != null && !isEditing) {
                    name = data.name
                    val nameParts = data.name.trim().split(" ", limit = 2)
                    firstName = nameParts.getOrElse(0) { "" }
                    lastName = nameParts.getOrElse(1) { "" }
                    email = data.email.ifEmpty { auth.currentUser?.email ?: "" }
                    chapter = data.school
                    year = data.year
                    statePref = data.state
                    bio = data.bio
                    pfpUrl = data.pfpUrl
                    instagram = data.instagram
                    twitter = data.twitter
                    facebook = data.facebook
                    linkedin = data.linkedin
                    chapterInstagram = data.chapterInstagram
                    username = data.username
                    usernameLastChanged = data.usernameLastChanged
                }
            }
        }
    }

    // Debounced username availability check
    LaunchedEffect(username, isEditing) {
        if (!isEditing || username.isEmpty() || username == (profile?.username ?: "")) {
            usernameAvailable = null
            usernameError = ""
            return@LaunchedEffect
        }
        if (!username.matches(Regex("[a-z0-9_]+"))) {
            usernameError = "Only lowercase letters, numbers, and underscores"
            usernameAvailable = null
            return@LaunchedEffect
        }
        if (username.length < 3) {
            usernameError = "At least 3 characters"
            usernameAvailable = null
            return@LaunchedEffect
        }
        if (containsProfanity(username)) {
            usernameError = "Username contains inappropriate content"
            usernameAvailable = null
            return@LaunchedEffect
        }
        usernameError = ""
        delay(600)
        isCheckingUsername = true
        try {
            val uid = auth.currentUser?.uid ?: return@LaunchedEffect
            val doc = db.collection("usernames").document(username).get().await()
            usernameAvailable = !doc.exists() || doc.getString("uid") == uid
        } catch (e: Exception) {
            usernameAvailable = null
        } finally {
            isCheckingUsername = false
        }
    }

    LaunchedEffect(Unit) {
        val uid = auth.currentUser?.uid
        if (uid != null) {
// Listen for pending connection requests
            db.collection("connectionRequests")
                .whereEqualTo("toUid", uid)
                .whereEqualTo("status", "pending")
                .addSnapshotListener { snapshot, _ ->
                    pendingRequestsCount = snapshot?.size() ?: 0
                }

// Listen for total connections
            db.collection("connections").document(uid)
                .addSnapshotListener { snapshot, _ ->
                    val connectedUids = snapshot?.get("connectedUids") as? List<*>
                    connectionCount = connectedUids?.size ?: 0
                }

// Listen for unread messages
            db.collection("messages")
                .addSnapshotListener { snapshot, _ ->
                    val messages = snapshot?.documents?.mapNotNull { it.toObject(ChatMessage::class.java) } ?: emptyList()

// Filter messages where current user is receiver
                    val unreadSenders = messages
                        .filter { it.receiverId == uid && it.senderId != uid }
                        .groupBy { it.senderId }
                        .keys
                        .toList()

                    unreadMessageCount = unreadSenders.size

// Get sender names
                    if (unreadSenders.isNotEmpty()) {
                        db.collection("users").whereIn("uid", unreadSenders.take(10))
                            .get()
                            .addOnSuccessListener { users ->
                                unreadMessagesFrom = users.documents.mapNotNull {
                                    it.toObject(UserProfile::class.java)?.name
                                }
                            }
                    } else {
                        unreadMessagesFrom = emptyList()
                    }
                }
        }
    }

    Box(modifier = Modifier.fillMaxSize()) {
// Background replaced with solid FBLA dark blue
        Box(modifier = Modifier.fillMaxSize().background(if (lightMode) Color(0xFFF0F4FF) else Color(0xFF0A1628)))
        if (!lightMode) Box(modifier = Modifier.fillMaxSize().background(Color.Black.copy(alpha = effectiveBgOpacity)))

        if (isProfileLoading) {
            CircularProgressIndicator(modifier = Modifier.align(Alignment.Center), color = primaryColor)
        } else {
            LazyColumn(modifier = Modifier.fillMaxSize(), contentPadding = PaddingValues(24.dp), horizontalAlignment = Alignment.CenterHorizontally) {
                item {
                    Spacer(modifier = Modifier.height(24.dp))
                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.End) {
                        IconButton(onClick = onSettingsClick) {
                            Icon(Icons.Default.Settings, contentDescription = "Settings", tint = primaryColor, modifier = Modifier.size(26.dp))
                        }
                    }
                    Box(
                        modifier = Modifier
                            .size(130.dp)
                            .fillMaxWidth(),
                        contentAlignment = Alignment.Center
                    ) {
                        Box(
                            modifier = Modifier
                                .size(120.dp)
                                .background(primaryColor, CircleShape)
                                .clip(CircleShape)
                                .clickable { pfpLauncher.launch("image/*") },
                            contentAlignment = Alignment.Center
                        ) {
                            if (isProcessingImage) {
                                CircularProgressIndicator(color = Color.Black)
                            } else if (pfpUrl.isNotEmpty()) {
                                AsyncImage(
                                    model = pfpUrl,
                                    contentDescription = null,
                                    modifier = Modifier.fillMaxSize(),
                                    contentScale = ContentScale.Crop
                                )
                            } else {
                                Text(firstName.take(1).ifEmpty { name.take(1).ifEmpty { "U" } }.uppercase(), color = Color.Black, style = MaterialTheme.typography.displayMedium.copy(fontSize = (MaterialTheme.typography.displayMedium.fontSize.value * textSizeMultiplier).sp), fontWeight = FontWeight.Bold)
                            }
                        }
                        var showPhotoOptions by remember { mutableStateOf(false) }
                        Box(
                            modifier = Modifier
                                .size(36.dp)
                                .background(Color.Black.copy(alpha = 0.85f), CircleShape)
                                .background(primaryColor.copy(alpha = 0.2f), CircleShape)
                                .align(Alignment.BottomEnd)
                                .clickable {
                                    if (pfpUrl.isNotEmpty()) showPhotoOptions = true
                                    else pfpLauncher.launch("image/*")
                                },
                            contentAlignment = Alignment.Center
                        ) {
                            Icon(Icons.Default.CameraAlt, null, tint = if (lightMode) Color(0xFF1A1A2E) else Color.White, modifier = Modifier.size(18.dp))
                        }
                        if (showPhotoOptions) {
                            Dialog(onDismissRequest = { showPhotoOptions = false }) {
                                Surface(shape = RoundedCornerShape(16.dp), color = if (lightMode) Color.White else Color(0xFF1A2744)) {
                                    Column(modifier = Modifier.padding(8.dp)) {
                                        TextButton(
                                            onClick = { showPhotoOptions = false; pfpLauncher.launch("image/*") },
                                            modifier = Modifier.fillMaxWidth()
                                        ) {
                                            Icon(Icons.Default.CameraAlt, null, tint = primaryColor, modifier = Modifier.size(18.dp))
                                            Spacer(Modifier.width(10.dp))
                                            Text("Change Photo", color = if (lightMode) Color(0xFF1A1A2E) else Color.White, fontWeight = FontWeight.Medium)
                                        }
                                        TextButton(
                                            onClick = {
                                                showPhotoOptions = false
                                                val uid = auth.currentUser?.uid ?: return@TextButton
                                                pfpUrl = ""
                                                db.collection("users").document(uid).update("pfpUrl", "")
                                            },
                                            modifier = Modifier.fillMaxWidth()
                                        ) {
                                            Icon(Icons.Default.Delete, null, tint = Color(0xFFCC3333), modifier = Modifier.size(18.dp))
                                            Spacer(Modifier.width(10.dp))
                                            Text("Remove Photo", color = Color(0xFFCC3333), fontWeight = FontWeight.Medium)
                                        }
                                    }
                                }
                            }
                        }
                    }
                    Spacer(modifier = Modifier.height(24.dp))

                    if (isEditing) {
                        Row(horizontalArrangement = Arrangement.spacedBy(8.dp), modifier = Modifier.fillMaxWidth()) {
                            Box(modifier = Modifier.weight(1f)) {
                                ProfileEditField(value = firstName, onValueChange = { firstName = it }, label = "First Name", lightMode = lightMode, accentColor = primaryColor)
                            }
                            Box(modifier = Modifier.weight(1f)) {
                                ProfileEditField(value = lastName, onValueChange = { lastName = it }, label = "Last Name", lightMode = lightMode, accentColor = primaryColor)
                            }
                        }
                        ProfileEditField(value = email, onValueChange = { email = it }, label = "Email", lightMode = lightMode, accentColor = primaryColor)
                        Spacer(modifier = Modifier.height(12.dp))
                        YearDropdown(selectedYear = year, onYearSelected = { year = it }, lightMode = lightMode, accentColor = primaryColor)
                        Spacer(modifier = Modifier.height(12.dp))
                        StateDropdown(selectedState = statePref, onStateSelected = { statePref = it }, lightMode = lightMode, accentColor = primaryColor)
                        val bioFg = if (lightMode) Color(0xFF1A1A2E) else Color.White
                        val bioBg = if (lightMode) Color(0xFFF0F4FF) else Color.White.copy(alpha = 0.06f)
                        Column(modifier = Modifier.fillMaxWidth().padding(bottom = 8.dp)) {
                            Text("Short Bio", fontSize = 11.sp, fontWeight = FontWeight.SemiBold, color = bioFg.copy(alpha = 0.6f), modifier = Modifier.padding(bottom = 6.dp))
                            Box(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .defaultMinSize(minHeight = 100.dp)
                                    .clip(RoundedCornerShape(14.dp))
                                    .background(bioBg)
                                    .border(1.dp, if (bio.isNotEmpty()) primaryColor.copy(alpha = 0.6f) else bioFg.copy(alpha = 0.2f), RoundedCornerShape(14.dp))
                                    .padding(horizontal = 14.dp, vertical = 12.dp)
                            ) {
                                BasicTextField(
                                    value = bio,
                                    onValueChange = { if (it.length <= 150) bio = it },
                                    modifier = Modifier.fillMaxWidth(),
                                    textStyle = androidx.compose.ui.text.TextStyle(color = bioFg, fontSize = 14.sp, lineHeight = 20.sp),
                                    cursorBrush = SolidColor(primaryColor),
                                    decorationBox = { inner ->
                                        if (bio.isEmpty()) Text("Tell people a little about yourself…", color = bioFg.copy(alpha = 0.35f), fontSize = 14.sp)
                                        inner()
                                    }
                                )
                            }
                            Text(
                                text = "${bio.length}/150",
                                fontSize = 11.sp,
                                color = if (bio.length >= 140) Color(0xFFFF7043) else bioFg.copy(alpha = 0.4f),
                                modifier = Modifier.align(Alignment.End).padding(end = 4.dp, top = 4.dp)
                            )
                        }

                        Spacer(modifier = Modifier.height(16.dp))
                        Text(
                            text = "USERNAME",
                            style = MaterialTheme.typography.labelMedium.copy(letterSpacing = 1.5.sp, fontWeight = FontWeight.Bold, fontSize = (12 * textSizeMultiplier).sp),
                            color = primaryColor,
                            modifier = Modifier.fillMaxWidth()
                        )
                        Spacer(modifier = Modifier.height(4.dp))
                        Text(
                            text = "3–20 chars, lowercase letters, numbers, underscores only. Changeable once every 30 days.",
                            style = MaterialTheme.typography.bodySmall.copy(fontSize = (11 * textSizeMultiplier).sp),
                            color = if (lightMode) Color(0xFF1A1A2E).copy(alpha = 0.6f) else Color.White.copy(alpha = 0.6f),
                            modifier = Modifier.fillMaxWidth()
                        )
                        Spacer(modifier = Modifier.height(8.dp))
                        val cooldownDaysLeft = if (usernameLastChanged > 0L && (profile?.username ?: "").isNotEmpty()) {
                            val cooldownMs = 30L * 24 * 60 * 60 * 1000
                            val elapsed = System.currentTimeMillis() - usernameLastChanged
                            if (elapsed < cooldownMs) ((cooldownMs - elapsed) / (24 * 60 * 60 * 1000) + 1).toInt() else 0
                        } else 0
                        ProfileEditField(
                            value = username,
                            onValueChange = {
                                val cleaned = it.lowercase().filter { c -> c.isLetterOrDigit() || c == '_' }.take(20)
                                username = cleaned
                                usernameAvailable = null
                            },
                            label = "@username",
                            errorMessage = when {
                                usernameError.isNotEmpty() -> usernameError
                                usernameAvailable == false -> "@$username is already taken"
                                else -> ""
                            },
                            lightMode = lightMode,
                            accentColor = primaryColor
                        )
                        when {
                            cooldownDaysLeft > 0 && username != (profile?.username ?: "") ->
                                Text("You can change your username again in $cooldownDaysLeft day(s)", style = MaterialTheme.typography.labelSmall.copy(fontSize = (11 * textSizeMultiplier).sp), color = Color(0xFFFF9800), modifier = Modifier.padding(start = 4.dp, top = 2.dp))
                            isCheckingUsername ->
                                Text("Checking availability…", style = MaterialTheme.typography.labelSmall.copy(fontSize = (11 * textSizeMultiplier).sp), color = if (lightMode) Color(0xFF1A1A2E).copy(alpha = 0.5f) else Color.White.copy(alpha = 0.5f), modifier = Modifier.padding(start = 4.dp, top = 2.dp))
                            usernameAvailable == true && usernameError.isEmpty() ->
                                Text("@$username is available!", style = MaterialTheme.typography.labelSmall.copy(fontSize = (11 * textSizeMultiplier).sp), color = Color(0xFF2ECC71), modifier = Modifier.padding(start = 4.dp, top = 2.dp))
                        }

                        Spacer(modifier = Modifier.height(16.dp))
                        Text(
                            text = "SOCIAL MEDIA (Optional)",
                            style = MaterialTheme.typography.labelMedium.copy(
                                letterSpacing = 1.5.sp,
                                fontWeight = FontWeight.Bold,
                                fontSize = (12 * textSizeMultiplier).sp
                            ),
                            color = primaryColor,
                            modifier = Modifier.fillMaxWidth()
                        )
                        Spacer(modifier = Modifier.height(8.dp))
                        ProfileEditField(
                            value = instagram,
                            onValueChange = {
                                instagram = it
                                val (isValid, error) = validateSocialMediaLink(it, "Instagram")
                                instagramError = error
                            },
                            label = "Instagram (instagram.com/username)",
                            errorMessage = instagramError,
                            lightMode = lightMode,
                            accentColor = primaryColor
                        )
                        ProfileEditField(
                            value = twitter,
                            onValueChange = {
                                twitter = it
                                val (isValid, error) = validateSocialMediaLink(it, "Twitter")
                                twitterError = error
                            },
                            label = "X/Twitter (twitter.com/username)",
                            errorMessage = twitterError,
                            lightMode = lightMode,
                            accentColor = primaryColor
                        )
                        ProfileEditField(
                            value = facebook,
                            onValueChange = {
                                facebook = it
                                val (isValid, error) = validateSocialMediaLink(it, "Facebook")
                                facebookError = error
                            },
                            label = "Facebook (facebook.com/username)",
                            errorMessage = facebookError,
                            lightMode = lightMode,
                            accentColor = primaryColor
                        )
                        ProfileEditField(
                            value = linkedin,
                            onValueChange = {
                                linkedin = it
                                val (isValid, error) = validateSocialMediaLink(it, "LinkedIn")
                                linkedinError = error
                            },
                            label = "LinkedIn (linkedin.com/in/username)",
                            errorMessage = linkedinError,
                            lightMode = lightMode,
                            accentColor = primaryColor
                        )
                        Spacer(modifier = Modifier.height(16.dp))
                        Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(8.dp), modifier = Modifier.fillMaxWidth()) {
                            Text(
                                text = "CHAPTER INSTAGRAM (Optional)",
                                style = MaterialTheme.typography.labelMedium.copy(
                                    letterSpacing = 1.5.sp,
                                    fontWeight = FontWeight.Bold,
                                    fontSize = (12 * textSizeMultiplier).sp
                                ),
                                color = primaryColor,
                                modifier = Modifier.weight(1f)
                            )
                            InfoIconButton("Enter your chapter's public Instagram username (without the @).\n\nOnce saved, the Resources tab will show a live feed of your chapter's latest Instagram posts — so all members can stay up to date without leaving the app.\n\nThe account must be public for the feed to load.", primaryColor, lightMode)
                        }
                        Spacer(modifier = Modifier.height(4.dp))
                        Text(
                            text = "Your chapter's public Instagram handle — posts will show in the Resources tab.",
                            style = MaterialTheme.typography.bodySmall.copy(fontSize = (11 * textSizeMultiplier).sp),
                            color = if (lightMode) Color(0xFF1A1A2E).copy(alpha = 0.6f) else Color.White.copy(alpha = 0.6f),
                            modifier = Modifier.fillMaxWidth()
                        )
                        Spacer(modifier = Modifier.height(8.dp))
                        ProfileEditField(
                            value = chapterInstagram,
                            onValueChange = { chapterInstagram = it.trimStart('@') },
                            label = "@chapter_handle",
                            lightMode = lightMode,
                            accentColor = primaryColor
                        )
                    } else {
                        Text(text = name.ifEmpty { "Member" }, style = MaterialTheme.typography.headlineMedium.copy(fontSize = (MaterialTheme.typography.headlineMedium.fontSize.value * textSizeMultiplier).sp), color = textColor, fontWeight = FontWeight.Black)
                        if (username.isNotEmpty()) {
                            Spacer(modifier = Modifier.height(2.dp))
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.Center,
                                modifier = Modifier.fillMaxWidth()
                            ) {
                                Text(
                                    "@$username",
                                    color = primaryColor,
                                    style = MaterialTheme.typography.bodyMedium.copy(fontSize = (14 * textSizeMultiplier).sp),
                                    fontWeight = FontWeight.Medium
                                )
                                Spacer(modifier = Modifier.width(4.dp))
                                IconButton(
                                    onClick = {
                                        clipboardManager.setText(buildAnnotatedString { append("@$username") })
                                        Toast.makeText(context, "Copied @$username", Toast.LENGTH_SHORT).show()
                                    },
                                    modifier = Modifier.size(28.dp)
                                ) {
                                    Icon(Icons.Default.ContentCopy, null, tint = primaryColor.copy(alpha = 0.6f), modifier = Modifier.size(15.dp))
                                }
                            }
                        }
                        Spacer(modifier = Modifier.height(6.dp))
                        Row(
                            horizontalArrangement = Arrangement.Center,
                            verticalAlignment = Alignment.CenterVertically,
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            if (year.isNotEmpty()) {
                                Box(
                                    modifier = Modifier
                                        .background(primaryColor.copy(alpha = 0.15f), RoundedCornerShape(20.dp))
                                        .border(1.dp, primaryColor.copy(alpha = 0.4f), RoundedCornerShape(20.dp))
                                        .padding(horizontal = 12.dp, vertical = 5.dp)
                                ) {
                                    Text(
                                        text = "Class of $year",
                                        color = primaryColor,
                                        style = MaterialTheme.typography.labelSmall.copy(fontSize = (11 * textSizeMultiplier).sp),
                                        fontWeight = FontWeight.Bold
                                    )
                                }
                                Spacer(modifier = Modifier.width(8.dp))
                            }
                            if (statePref.isNotEmpty()) {
                                Box(
                                    modifier = Modifier
                                        .background(primaryColor.copy(alpha = 0.15f), RoundedCornerShape(20.dp))
                                        .border(1.dp, primaryColor.copy(alpha = 0.4f), RoundedCornerShape(20.dp))
                                        .padding(horizontal = 12.dp, vertical = 5.dp)
                                ) {
                                    Text(
                                        text = statePref,
                                        color = primaryColor,
